mapper.select:
SELECT id, operator_id, operator_name, operation, ip, operate_time
FROM `operation_log`


        AND operator_id = #{operatorId}


        AND operator_name LIKE CONCAT('%', #{operatorName}, '%')


        AND operation LIKE CONCAT('%', #{operation}, '%')


        AND operate_time >= #{startTime}


        AND operate_time <= #{endTime}


ORDER BY operate_time DESC, id DESC
